Lemma absent_has_hash : forall U D h, dwf U D -> 0 <= h ->
  Forall (fun j => dhs D j <> h) (chain (dlk D) (dhd D (bkt h))) -> has_hash (dhs D) (Z.to_nat (dN D)) h = false.
Proof.
