Lemma dwf_insert : forall U D u h v sid,
  dwf U D -> In u U -> hashU u = h ->
  v = dhd D (bkt h) ->
  Forall (fun j => dhs D j <> h) (chain (dlk D) v) ->
  0 <= sid < 2^32 ->
  dwf U (dins D (bkt h) h v sid (Z.of_nat (length u))).
